+package release
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"strings"
+
+	"github.com/blang/semver/v4"
+	"github.com/google/go-github/v32/github"
+	"go.uber.org/zap"
+)
+
+// Info contains the version information returned by an update check.
+type Info struct {
+	CurrentVersion   string
+	LatestVersion    string
+	UpdateAvailable  bool
+	LatestVersionURL string
+}
+
+// Check retrieves the latest release and compares it with the current version.
+func Check(ctx context.Context, version string) (Info, error) {
+	current, err := semver.ParseTolerant(version)
+	if err != nil {
+		return checkError(Info{CurrentVersion: version}, fmt.Errorf("parsing current version: %w", err))
+	}
+
+	info := Info{CurrentVersion: current.String()}
+	client := github.NewClient(nil)
+	latest, _, err := client.Repositories.GetLatestRelease(ctx, "flipt-io", "flipt")
+	if err != nil {
+		return checkError(info, fmt.Errorf("getting latest release: %w", err))
+	}
+	if latest == nil {
+		return checkError(info, errors.New("getting latest release: empty response"))
+	}
+
+	latestVersion, err := semver.ParseTolerant(latest.GetTagName())
+	if err != nil {
+		return checkError(info, fmt.Errorf("parsing latest version: %w", err))
+	}
+
+	info.LatestVersion = latestVersion.String()
+	info.LatestVersionURL = latest.GetHTMLURL()
+	info.UpdateAvailable = current.LT(latestVersion)
+	return info, nil
+}
+
+func checkError(info Info, err error) (Info, error) {
+	zap.L().Warn("checking for updates", zap.Error(err))
+	return info, err
+}
+
+// Is reports whether version is a proper release rather than a development build.
+func Is(version string) bool {
+	version = strings.ToLower(strings.TrimSpace(version))
+	if version == "" || version == "dev" || version == "snapshot" || version == "rc" {
+		return false
+	}
+
+	for _, marker := range []string{"-dev", "-snapshot", "-rc"} {
+		if strings.Contains(version, marker) {
+			return false
+		}
+	}
+	return true
+}
